from copy import deepcopy
from pathlib import Path
from hashlib import sha256
import json
from tools.synthetic_inspection_corpus import Corpus, canonical, PROFILE
from biocompiler.ir.mechanism import MechanismProgram, MechanismNode
from biocompiler.semantics.realization import Observable
from biocompiler.semantics.types import BOOLEAN
from biocompiler.verification.evidence import CheckResult, DependencySnapshot
from biocompiler.registry.components import ComponentRegistry, SelectionRequest, SelectionResult, RegistryLock
from biocompiler.ir.component_contracts import ComponentRecord
root=Path('.'); original=Corpus(); cases=[]
def add(name,api,op,authority,call,value,properties=lambda x:{},code=None,path=None):
    payload={'profile':PROFILE,'limits':None,**authority}
    try:
        observed=call(); public={'value':value(observed),'properties':properties(observed)}; error=None
        if op=='inspect-synthetic-mechanism': expected={'nodes':public['value']}
        elif api=='CheckResult.exercised_requirement_ids':expected={'exercised_requirement_ids':public['value'],'freshness':None}
        elif api in ('CheckResult.freshness','CheckResult.is_fresh'):
            record=CheckResult.from_dict(authority['record']); report=record.freshness(DependencySnapshot(authority['current']))
            expected={'exercised_requirement_ids':list(record.exercised_requirement_ids),'freshness':{'changed_dependencies':list(report.changed_dependencies),'fresh':report.fresh,'status':report.status}}
        elif op=='compare-synthetic-dependencies':expected={'changed_dependencies':public['value']}
        elif op=='lock-synthetic-registry':expected={'lock':public['value']}
        elif op=='resolve-synthetic-registry':expected={'instances':public['value']}
        elif op=='select-synthetic-registry':expected={'selection':public['value'],'outcome':observed.outcome}
        elif op=='verify-synthetic-registry-selection':expected={'valid':public['value']}
        else:expected={'outcome':public['value']}
    except (TypeError,ValueError) as exc:
        if code is None:raise
        detail={'module':type(exc).__module__,'type':type(exc).__name__,'message':str(exc)}
        public={'error':detail}; error={'code':code,'path':path,'message':str(exc)};expected=None
    cases.append({'id':'supplemental/'+name,'api':api,'operation':op,'payload':payload,'expected_value':expected,'error':error,'expected_public':public,'evidence':{'capture':'original_python_helper_execution','python_module':call.__module__,'case':name}})
def graph(unicode=False,reverse=False):
    names=['z','a','aa','finish'] if not unicode else ['β','𐐀','é','résultat']
    z,a,b,out=names
    def node(id,kind,inputs=(),attributes=None):return MechanismNode(id,kind,Observable('port:'+id,BOOLEAN,'cell'),inputs,attributes or {})
    nodes=[node(z,'constant',attributes={'value':True}),node(a,'constant',attributes={'value':False}),node(b,'not',(a,)),node(out,'output',(b,))]
    return MechanismProgram('ordered '+('β' if unicode else 'ascii'),tuple(reversed(nodes) if reverse else nodes),(out,))
for unicode,reverse in [(False,False),(False,True),(True,True)]:
    m=graph(unicode,reverse)
    add(f'topological-{unicode}-{reverse}','MechanismProgram.topological_nodes','inspect-synthetic-mechanism',{'mechanism':m.to_dict()},lambda m=m:m.topological_nodes(),lambda ns:[n.to_dict() for n in ns])
# Native test examples retain independently observed original source cases for
# each existing helper, including every distinct historical resolver rejection.
seen=set()
for row in original.cases:
    key=(row['api'],row['error']['message'] if row['error'] else None)
    if key in seen:continue
    seen.add(key);r=deepcopy(row);r['id']='supplemental/original/'+str(len(cases));cases.append(r)
record=deepcopy(next(r['payload']['record'] for r in original.cases if r['api']=='CheckResult.exercised_requirement_ids'))
record.update(outcome='unknown',checked_requirement_ids=['z','a','part'],diagnostics=[],counterexamples=[])
record['coverage']=[{'requirement_id':id,'activation_deadlines_checked':a,'inactive_deadlines_checked':i,'incomplete_episode_count':0,'cancelled_episode_count':0} for id,a,i in [('z',1,1),('part',0,1),('a',2,3)]]
c=CheckResult.from_dict(record)
add('coverage-retains-order','CheckResult.exercised_requirement_ids','inspect-synthetic-check-result',{'record':record,'query':'coverage','current':None},lambda:c.exercised_requirement_ids,list)
previous=deepcopy(c.dependencies.to_dict())
for name,mutation in [('equal',lambda d:None),('numeric-kinds',lambda d:d['settings'].update(number=1.0)),('unicode',lambda d:d['settings'].update(note='β𐐀')),('multiple',lambda d:d.update(checker='other',history='b'*64))]:
    before=deepcopy(previous);before['settings']['number']=1;current=deepcopy(before);mutation(current)
    left,right=DependencySnapshot(before),DependencySnapshot(current)
    add('dependencies-'+name,'DependencySnapshot.changed','compare-synthetic-dependencies',{'previous':before,'current':current},lambda left=left,right=right:left.changed(right),list)
for name,current in [('none',None),('scalar',3),('array',[])]:
    add('dependencies-wrong-'+name,'DependencySnapshot.changed','compare-synthetic-dependencies',{'previous':previous,'current':current},lambda current=current:c.dependencies.changed(current),list,code='synthetic_inspection_type',path='payload.current')
for api in ['freshness','is_fresh']:
    add('check-wrong-'+api,'CheckResult.'+api,'inspect-synthetic-check-result',{'record':record,'query':'freshness','current':None},lambda api=api:getattr(c,api)(None),lambda x:x,code='synthetic_inspection_type',path='payload.current')
select=next(r for r in original.cases if r['api']=='ComponentRegistry.select' and r['error'] is None)
a=deepcopy(select['payload']);registry=ComponentRegistry.from_dict(a['registry']);request=SelectionRequest.from_dict(a['request'])
add('verify-null','ComponentRegistry.verify_selection','verify-synthetic-registry-selection',{'registry':a['registry'],'request':a['request'],'selection':None},lambda:registry.verify_selection(request,None),lambda x:x)
# Freshness and is_fresh are both observed directly, with changed dependencies.
current=deepcopy(previous);current['settings']['unicode']='β𐐀';dependency=DependencySnapshot(current)
for api in ['freshness','is_fresh']:
    add('stale-'+api,'CheckResult.'+api,'inspect-synthetic-check-result',{'record':record,'query':'freshness','current':current},lambda api=api:getattr(c,api)(dependency),lambda x:{'changed_dependencies':list(x.changed_dependencies)} if hasattr(x,'changed_dependencies') else x,lambda x:{'fresh':x.fresh,'status':x.status} if hasattr(x,'fresh') else {})
paths=['src/biocompiler/ir/mechanism.py','src/biocompiler/verification/evidence.py','src/biocompiler/registry/components.py','src/biocompiler/ir/component_contracts.py','src/biocompiler/semantics/realization.py','src/biocompiler/semantics/types.py']
doc={'schema_version':'biocompiler.synthetic_inspection_supplemental.v1','source_files':{p:sha256((root/p).read_bytes()).hexdigest() for p in paths},'capture_source':Path(__file__).read_text(),'cases':cases}
Path('tests/conformance/synthetic-inspection-supplemental-v1.json').write_bytes(canonical(doc)+b'\n')
print('captured',len(cases),'cases', 'errors',sum(r['error'] is not None for r in cases))
